contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _val, uint _val2) public payable {
        require(true);

        bool reverted1;
        c.SetMinSum(_val); if (__ESBMC_reverted()) return;
        reverted1 = false;

        uint minSumAfterFirst = c.MinSum(); if (__ESBMC_reverted()) return;

        bool reverted2;
        c.SetMinSum(_val2); if (__ESBMC_reverted()) return;
        reverted2 = false;

        assert(!reverted1 && !reverted2 && minSumAfterFirst == _val && c.MinSum() == _val2);
    }

    receive() external payable {}
}

