pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 _val, uint256 _val2) internal {
        vm.assume(true);
        bool reverted1;
        try c.SetMinSum(_val) {} catch { return; }
        reverted1 = false;
        uint256 minSumAfterFirst;
        try c.MinSum() returns (uint256 __r) { minSumAfterFirst = __r; } catch { return; }
        bool reverted2;
        try c.SetMinSum(_val2) {} catch { return; }
        reverted2 = false;
        assertTrue(!reverted1 && !reverted2 && minSumAfterFirst == _val && c.MinSum() == _val2);
    }

    function testFuzz_run(uint256 _val, uint256 _val2) public {
        _run(_val, _val2);
    }

    receive() external payable {}
}
